function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's has 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase letters a-z.';
  return null;
}

