function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const style = rand();
  let s = '';
  if (style < 0.25) {
    // Plain random letters, from a narrow or the full alphabet.
    const width = rand() < 0.5 ? 3 : 26;
    for (let i = 0; i < n; i++) s += alphabet[Math.floor(rand() * width)];
  } else {
    // Glue together alphabet pieces of random start and length, so runs meet and break.
    while (s.length < n) {
      const start = Math.floor(rand() * 26);
      const length = 1 + Math.floor(rand() * (size === 'large' && rand() < 0.1 ? 26 : 8));
      s += alphabet.slice(start, start + length);
    }
    s = s.slice(0, n);
  }
  return [s];
}
